const adaptiveGradeMeta={"1":{label:"Grade 1",min:1,max:2},"2":{label:"Grade 2",min:2,max:3},"3":{label:"Grade 3",min:3,max:4},"4":{label:"Grade 4",min:4,max:5},all:{label:"All Grades",min:1,max:5}};
