function topicAccuracy(t){let s=st.stats[t]||{c:0,n:0};return s.n?s.c/s.n:.55}
function adaptiveLevel(t){let s=st.stats[t]||{c:0,n:0},acc=topicAccuracy(t),m=adaptiveMeta(),target;if(s.n<3)target=Math.round((m.min+m.max)/2);else if(acc>=.88)target=m.max;else if(acc>=.75)target=Math.min(m.max,m.min+2);else if(acc>=.58)target=Math.min(m.max,m.min+1);else target=m.min;return Math.max(m.min,Math.min(m.max,target))}
function pickAdaptive(){let pool=adaptivePool(),available=pool.filter(q=>!adaptiveUsed.has(q.q));if(!available.length){adaptiveUsed.clear();available=pool}
  if(adaptiveMisses.length&&Math.random()<.32){let miss=adaptiveMisses[0],same=available.filter(q=>q.t===miss.t&&q.q!==miss.q);if(same.length){let q=shuffle(same)[0];adaptiveMisses.shift();adaptiveUsed.add(q.q);return q}}
  let ts=[...new Set(available.map(q=>q.t))],weighted=[];ts.forEach(t=>{let s=st.stats[t]||{c:0,n:0},acc=topicAccuracy(t),w=Math.max(1,Math.round((1-acc)*8)+(s.n<3?3:0));for(let x=0;x<w;x++)weighted.push(t)});let t=weighted[Math.floor(Math.random()*weighted.length)]||ts[0],target=adaptiveLevel(t);let candidates=available.filter(q=>q.t===t).sort((a,b)=>Math.abs(a.d-target)-Math.abs(b.d-target));let top=candidates.slice(0,Math.min(4,candidates.length)),q=shuffle(top)[0]||shuffle(available)[0];adaptiveUsed.add(q.q);return q}
